SELECT fdr.id, fdr.user_id, fdr.user_name, COALESCE(auth.real_name, su.nick_name) AS nick_name, fdr.task_id, ft.task_name, fdr.file_task_id, fdr.file_task_name, fdr.file_name, fdr.download_time, fdr.del_flag, fdr.create_by, fdr.create_time, fdr.update_by, fdr.update_time, fdr.remark FROM file_download_record fdr LEFT JOIN file_task ft ON ft.id = fdr.task_id LEFT JOIN sys_user su ON fdr.user_id = su.user_id LEFT JOIN ( SELECT user_id, real_name FROM ( SELECT user_id, real_name, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY auth_time DESC) AS rn FROM auth_info WHERE del_flag = '0' AND auth_status = '5' ) t WHERE rn = 1 ) auth ON auth.user_id = fdr.user_id
and fdr.del_flag = '0' and fdr.user_id = #{userId} and fdr.user_name like concat('%', #{userName}, '%')
AND ( COALESCE(auth.real_name, su.nick_name) LIKE concat('%', #{nickName}, '%') )
and fdr.file_task_id = #{fileTaskId} and fdr.file_task_name like concat('%', #{fileTaskName}, '%') and fdr.file_name like concat('%', #{fileName}, '%') and fdr.create_by like concat('%', #{createBy}, '%') and fdr.download_time = #{downloadTime}
and fdr.create_time >= #{params.beginTime}
and fdr.create_time <= #{params.endTime}
and ft.task_name like concat('%', #{taskName}, '%')
order by fdr.create_time desc

