user_id = #{userId}, user_name = #{userName}, task_id = #{taskId}, file_task_id = #{fileTaskId}, file_task_name = #{fileTaskName}, file_name = #{fileName}, download_time = #{downloadTime}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where id = #{id}
